"""Independent small-v cubic control for clean psi_coefficients (1703.03967v3 App. C)."""
import hashlib,json,math,numpy as np,torch
from torchwave.approximants.precession_msa_angles_clean import assemble_precession_msa_angles
from torchwave.approximants.precession_msa_initial_clean import cubic_coefficients,ordered_roots
from torchwave.approximants.precession_msa_pn_clean import precession_averages,flux_coefficients,reciprocal_coefficients,psi_coefficients
CASES=[(35.,25.,[.2,.1,.2],[-.1,.15,-.1]),(45.,15.,[.45,-.2,.3],[.1,.2,-.25]),(30.,10.,[.12,-.31,.44],[-.22,.18,-.07])]
def one(m1,m2,c1,c2):
 s1=torch.tensor(c1,dtype=torch.float64);s2=torch.tensor(c2,dtype=torch.float64);M=m1+m2;x1=m1/M;x2=m2/M;eta=x1*x2;q=x2/x1;delta=x1-x2;f=torch.tensor([20.],dtype=torch.float64);a=assemble_precession_msa_angles(f,m1,m2,s1,s2,f_ref=20.,order=5);r=a['roots'][0];s3,sm,sp=[float(z) for z in r];sav=float(a['sav']);v0=float((math.pi*M*4.925490947641267e-6*f[0])**(1/3));S1=x1*x1*s1;S2=x2*x2*s2;s1sq=float((S1*S1).sum());s2sq=float((S2*S2).sum());xi=float((1+q)*S1[2]+(1+1/q)*S2[2]);av=precession_averages(float(a['c1']),xi,q,eta,sp,sm,s1sq,s2sq,v0);g=reciprocal_coefficients(flux_coefficients(eta,q,av['s1l'],av['s2l'],s1sq,s2sq,(sav-s1sq-s2sq)/2,av['s1l2'],av['s2l2'],av['s1ls2l']));p1,p2=psi_coefficients(eta,delta,q,xi,float(a['c1']),sav,s1sq,s2sq,g['g0'],g['g2']);
 vals=[]
 for v in (.01,.005,.0025):
  L=eta/v;J=math.sqrt(L*L+2*float(a['c1'])*L/eta+sav);z=ordered_roots(*cubic_coefficients(torch.tensor(q,dtype=torch.float64),torch.tensor(eta,dtype=torch.float64),torch.tensor(delta,dtype=torch.float64),torch.tensor(s1sq,dtype=torch.float64),torch.tensor(s2sq,dtype=torch.float64),torch.tensor(L,dtype=torch.float64),torch.tensor(J,dtype=torch.float64),torch.tensor(xi,dtype=torch.float64)));R=(1-xi*v)*math.sqrt(float(z[2]-z[0]))*v/math.sqrt(eta*delta*delta);pred=1+2*float(p1)/3*v+(float(p2)/3-float(g['g2']/g['g0']))*v*v;vals.append({'v':v,'R':R,'predicted':pred,'remainder':R-pred,'remainder_over_v3':(R-pred)/v**3})
 return {'masses':[m1,m2],'eta':eta,'delta':delta,'q':q,'c1':float(a['c1']),'sav':sav,'psi1':float(p1),'psi2':float(p2),'g0':float(g['g0']),'g2':float(g['g2']),'samples':vals,'equations':['1703.03967v3 App. C psi1/psi2','1703.03967v3 cubic roots and Ssq-sol']}
if __name__=='__main__':
 out={'provenance':'Fresh clean modules; direct cubic roots and prescribed coefficients, no fitted parameters. Remainder should remain bounded as v decreases.','cases':[one(*c) for c in CASES],'clean_sha256':{n:hashlib.sha256(open('src/torchwave/approximants/'+n,'rb').read()).hexdigest() for n in ('precession_msa_initial_clean.py','precession_msa_angles_clean.py','precession_msa_pn_clean.py')}};out['script_sha256']=hashlib.sha256(open(__file__,'rb').read()).hexdigest();open('docs/reviews/2026-09-13-parity-review/msa-psi-asymptotic-reference.json','w').write(json.dumps(out,indent=2)+'\n');print([(x['masses'],[round(y['remainder_over_v3'],3) for y in x['samples']]) for x in out['cases']])
